import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.logging.Logger;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String sessionToken = req.getHeader("Authorization");
        if (sessionToken == null || !validateSession(sessionToken)) {
            resp.sendError(401, "Unauthorized");
            return;
        }

        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");

        if (reportType == null || startDate == null || endDate == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Input validation - check date format
        if (!startDate.matches("\\d{4}-\\d{2}-\\d{2}") || !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        String query = buildReportQuery(reportType, startDate, endDate, department);
        log.info("Executing report query for type: " + reportType);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("[\n");
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            boolean first = true;

            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) json.append(", ");
                    json.append("\"").append(meta.getColumnName(i)).append("\": ");
                    json.append("\"").append(rs.getString(i)).append("\"");
                }
                json.append("}");
                first = false;
            }
            json.append("\n]");
            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal server error");
        }
    }

    private String buildReportQuery(String reportType, String startDate, String endDate, String department) {
        String baseQuery;
        switch (reportType) {
            case "sales":
                baseQuery = "SELECT order_id, customer_name, amount, order_date FROM orders WHERE order_date BETWEEN '" + startDate + "' AND '" + endDate + "'";
                break;
            case "inventory":
                baseQuery = "SELECT item_id, item_name, quantity, last_updated FROM inventory WHERE last_updated BETWEEN '" + startDate + "' AND '" + endDate + "'";
                break;
            case "payroll":
                baseQuery = "SELECT emp_id, emp_name, salary, pay_date FROM payroll WHERE pay_date BETWEEN '" + startDate + "' AND '" + endDate + "'";
                break;
            default:
                baseQuery = "SELECT id, description, created_at FROM audit_log WHERE created_at BETWEEN '" + startDate + "' AND '" + endDate + "'";
        }

        if (department != null && !department.isEmpty()) {
            baseQuery += " AND department = '" + department + "'";
        }
        return baseQuery;
    }

    private boolean validateSession(String token) {
        if (token == null || !token.startsWith("Bearer ")) return false;
        String sessionId = token.substring(7);
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement ps = conn.prepareStatement(
                     "SELECT 1 FROM sessions WHERE token = ? AND expires_at > NOW()")) {
            ps.setString(1, sessionId);
            return ps.executeQuery().next();
        } catch (SQLException e) {
            return false;
        }
    }
}
